(function(root){
'use strict';
const C=typeof module==='object'&&module.exports?require('./core.js'):root.THCore;
const W=typeof module==='object'&&module.exports?require('./workbench.js'):root.THWorkbench;
const Studio=typeof module==='object'&&module.exports?require('./studio-markup.js'):root.THStudioMarkup;
const K=typeof module==='object'&&module.exports?require('./creator-core.js'):root.THCreator;
const Creator=typeof module==='object'&&module.exports?require('./creator-markup.js'):root.THCreatorMarkup;
const X=typeof module==='object'&&module.exports?require('./experience-core.js'):root.THExperience;
const Experience=typeof module==='object'&&module.exports?require('./experience-markup.js'):root.THExperienceMarkup;
function build(data){
const errors=C.validate(data);if(errors.length)throw Error(errors.join('\n'));
const E=C.escape,cfg=data.config,base=(C.url(cfg.siteUrl)||'').replace(/\/$/,'');
const paths={
  arrow:'M7 17 17 7M7 7h10v10', right:'m9 5 7 7-7 7', search:'m21 21-5-5M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
  bookmark:'M6 3h12v18l-6-4-6 4z', sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5',
  menu:'M3 6h18M3 12h18M3 18h18', close:'m6 6 12 12M6 18 18 6', clock:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z', command:'M9 7V4a2 2 0 1 0-2 2h10a2 2 0 1 0-2-2v16a2 2 0 1 0 2-2H7a2 2 0 1 0 2 2V7z',
  chip:'M7 7h10v10H7zM9 1v4m6-4v4M9 19v4m6-4v4M1 9h4m-4 6h4m14-6h4m-4 6h4',
  shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6zM8 12l3 3 5-6', share:'m9 11 6-4m-6 6 6 4M8 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0m14-8a3 3 0 1 1-6 0 3 3 0 0 1 6 0m0 16a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  check:'m5 12 4 4L19 6', top:'m6 13 6-6 6 6M12 7v14', mail:'M2 5h20v14H2zM2 5l10 8L22 5', external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7', edit:'m4 16-1 5 5-1L21 7l-5-5zM13 5l6 6'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const fb='<svg class="icon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M14 22v-9h3l.5-4H14V6.5c0-1.1.3-1.5 1.5-1.5H18V1.3A28 28 0 0 0 15 1c-3 0-5 1.8-5 5v3H7v4h3v9z"/></svg>';
const logo='<svg class="brand-mark" viewBox="0 0 44 44" fill="none" aria-hidden="true"><rect x=".75" y=".75" width="42.5" height="42.5" rx="12" stroke="currentColor" stroke-opacity=".35"/><path d="M8 12h19v5h-7v17h-5V17H8z" fill="currentColor"/><path d="M28 12h5v8h5v5h-5v9h-5zM20 20h8v5h-8z" fill="currentColor" opacity=".65"/></svg>';
const brand=p=>`<a class="brand" href="${p}index.html" aria-label="${E(cfg.name)} — Trang chủ">${C.image(cfg.logoImage,150000)?`<img class="brand-mark custom-brand" src="${E(cfg.logoImage)}" width="44" height="44" alt="">`:logo}<span>${E(cfg.name)}<small>CÔNG NGHỆ · GÓC NHÌN MỚI</small></span></a>`;
const date=a=>new Date(a.date+'T00:00:00Z').toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'UTC'});
const cat=a=>data.categories.find(c=>c.id===a.category);
const articleUrl=(a,p='')=>`${p}bai-viet/${a.id}.html`;
const imageUrl=(a,p='')=>C.image(a.customImage,250000)||`${p}assets/${a.image}.svg`;
const tag=a=>`<span class="tag tag-${a.category}">${E(cat(a).short||cat(a).name)}</span>`;
const miniMeta=a=>`<span>${date(a)}</span><span class="meta-dot">·</span><span>${a.minutes} phút đọc</span>`;
function card(a,p='',cls='') { return `<article class="article-card ${cls}" data-article-id="${a.id}"><a class="card-visual" href="${articleUrl(a,p)}" tabindex="-1" aria-hidden="true"><img src="${imageUrl(a,p)}" alt="" loading="lazy" width="640" height="400"><span class="visual-arrow">${icon('arrow')}</span></a><div class="card-body"><div class="card-top">${tag(a)}<button class="icon-button bookmark" data-save="${a.id}" aria-label="Lưu bài: ${E(a.title)}" aria-pressed="false">${icon('bookmark')}</button></div><h3><a href="${articleUrl(a,p)}">${E(a.title)}</a></h3><p>${E(a.excerpt)}</p><div class="meta">${miniMeta(a)}</div></div></article>`; }
function legacyHead(title,description,p='',file='index.html',type='website') {
 const canonical=base?`${base}/${file}`:'';
 return `<!doctype html><html lang="vi" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080e18"><meta name="color-scheme" content="dark light"><title>${E(title)}</title><meta name="description" content="${E(description)}">${canonical?`<link rel="canonical" href="${E(canonical)}">`:''}<meta property="og:locale" content="vi_VN"><meta property="og:type" content="${type}"><meta property="og:site_name" content="${E(cfg.name)}"><meta property="og:title" content="${E(title)}"><meta property="og:description" content="${E(description)}">${canonical?`<meta property="og:url" content="${E(canonical)}"><meta property="og:image" content="${base}/assets/horizon-portal.webp"><meta property="og:image:width" content="1920"><meta property="og:image:height" content="1072">`:''}<meta name="twitter:card" content="summary_large_image"><link rel="icon" href="${p}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="${p}assets/style.css"><script>try{const t=JSON.parse(localStorage.getItem('th-theme'));if(t==='light'||t==='dark')document.documentElement.dataset.theme=t}catch(e){}</script><script src="${p}site-data.js" defer></script><script src="${p}assets/core.js" defer></script><script src="${p}assets/static-routes.js" defer></script><script src="${p}assets/app.js" defer></script>`;
}
function legacyHeader(p='') {return `<a class="skip-link" href="#main">Đến nội dung chính</a><div class="preview-banner" id="preview-banner" hidden>Đang xem bản nháp trên thiết bị này. <a href="${p}bien-tap.html">Về bàn biên tập</a><button id="exit-preview">Thoát xem trước</button></div><header class="site-header"><div class="container header-inner">${brand(p)}<nav class="desktop-nav" aria-label="Điều hướng chính"><a href="${p}index.html#kham-pha">Khám phá</a><a href="${p}index.html#bai-viet">Cẩm nang</a><a href="${p}index.html#ve-kenh">Về kênh</a><a href="${p}index.html#cong-dong">Cộng đồng</a></nav><div class="header-actions"><button class="icon-button" data-open-search aria-label="Tìm kiếm bài viết">${icon('search')}</button><button class="icon-button theme-toggle" aria-label="Chuyển giao diện sáng hoặc tối">${icon('sun')}</button><button class="button button-small button-blue desktop-follow" data-facebook>${fb}Theo dõi kênh${icon('arrow')}</button><button class="icon-button menu-button" aria-label="Mở menu" aria-controls="mobile-menu" aria-expanded="false">${icon('menu')}</button></div></div><nav id="mobile-menu" class="mobile-menu" aria-label="Điều hướng điện thoại" hidden><a href="${p}index.html#kham-pha">Khám phá</a><a href="${p}index.html#diem-bat-dau">Khám phá theo gu</a>${X.labs(data).length?`<a href="${p}index.html#giai-ma-nhanh">Giải mã nhanh</a>`:''}<a href="${p}index.html#bai-viet">Cẩm nang công nghệ</a><a href="${p}index.html#ve-kenh">Về Tech Horizon</a><a href="${p}index.html#cong-dong">Cộng đồng</a><button data-facebook>${fb}Theo dõi trên Facebook${icon('arrow')}</button></nav></header>`;}
function legacyFooter(p='') {return `<footer class="site-footer"><div class="container"><div class="footer-top"><div>${brand(p)}<p>Công nghệ gần hơn.<br>Góc nhìn mở hơn.</p></div><div><h3>Khám phá</h3><a href="${p}index.html#bai-viet">Tất cả cẩm nang</a><a href="${p}index.html#bai-viet" data-footer-saved>Bài đã lưu</a><a href="${p}index.html#kham-pha">Chuyên mục</a></div><div><h3>Tech Horizon</h3><a href="${p}index.html#ve-kenh">Câu chuyện của kênh</a><a href="${p}index.html#cong-dong">Kết nối & góp ý</a><a href="${p}chinh-sach.html">Quyền riêng tư</a></div><div class="footer-social"><h3>Cùng bắt kịp công nghệ</h3><p>Một góc nhìn mới, bắt đầu từ<br>một điều bạn tò mò.</p><button class="text-button" data-facebook>${fb}Ghé kênh Facebook${icon('arrow')}</button></div></div><div class="footer-bottom"><span>© <span data-year>2026</span> ${E(cfg.name)}. Công nghệ dành cho mọi người.</span><span>Được xây dựng dành riêng cho Tech Horizon <span class="blue-dot"></span></span><a href="${p}bien-tap.html">Bàn biên tập ${icon('edit')}</a></div></div></footer><button class="back-top icon-button" aria-label="Về đầu trang">${icon('top')}</button><div class="toast" role="status" aria-live="polite" id="toast"></div><dialog id="search-dialog" class="search-dialog"><form method="dialog" class="dialog-heading"><span>Tìm điều bạn tò mò</span><button class="icon-button" aria-label="Đóng tìm kiếm">${icon('close')}</button></form><label class="search-field">${icon('search')}<input id="global-search" type="search" placeholder="AI, RAM, bảo mật…" autocomplete="off" maxlength="100" aria-label="Nhập từ khóa tìm bài"></label><div id="global-results" class="search-results" aria-live="polite"></div><p class="search-hint">Nhấn Esc để đóng · Ctrl / ⌘ + K để tìm kiếm</p></dialog><dialog id="info-dialog" class="info-dialog"><form method="dialog" class="dialog-heading"><span id="info-title">Tech Horizon</span><button class="icon-button" aria-label="Đóng thông báo">${icon('close')}</button></form><div id="info-content"></div></dialog>`;}
function footer(p=''){return legacyFooter(p).replace('<div class="footer-bottom">',`<nav class="footer-utility" aria-label="Trang hỗ trợ"><a href="${p}gioi-thieu.html">Giới thiệu & hợp tác</a><a href="${p}dieu-hanh.html">Trạm điều hành</a><a href="${p}du-lieu.html">Dữ liệu & hiển thị</a><a href="${p}huong-dan.html">Hướng dẫn sử dụng</a><a href="${p}feed.xml">RSS</a></nav><div class="footer-bottom">`);}
function legacyHome(){
 const featured=data.articles.find(a=>a.featured)||data.articles[0];
 const json=JSON.stringify({'@context':'https://schema.org','@type':'WebSite',name:cfg.name,url:base,description:cfg.description,inLanguage:'vi-VN'}).replace(/</g,'\\u003c');
 return head(`${cfg.name} — Công nghệ gần hơn, mỗi ngày`,cfg.description)+`<script type="application/ld+json">${json}</script></head><body data-page="home" data-base="">${header()}<main id="main"><section class="hero container" id="trang-chu"><div class="hero-art" aria-hidden="true"><img src="assets/horizon-globe.webp" alt="" width="1536" height="1024" fetchpriority="high"><div class="hero-art-fade"></div><span class="orbit-label"><span class="blue-dot"></span> A NEW PERSPECTIVE</span></div><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> KHÁM PHÁ · HIỂU RÕ · ỨNG DỤNG</div><h1>Công nghệ<br>không còn<br><span>khó khăn.</span><span class="heading-star" aria-hidden="true">✳</span></h1><p>Cùng <strong>Tech Horizon</strong> bắt kịp thế giới số bằng góc nhìn dễ hiểu nhất. Từ điều bạn tò mò đến điều bạn có thể làm.</p><div class="hero-buttons"><a class="button button-blue" href="#bai-viet">Khám phá cẩm nang${icon('arrow')}</a><button class="button button-outline" data-facebook>${fb}Kết nối Facebook</button></div><div class="hero-note"><span class="mini-avatar">TH</span><span>Góc nhìn mới về công nghệ.<br><strong>Dành cho cả người mới bắt đầu.</strong></span><span class="note-line"></span></div></div><a class="hero-feature" href="${articleUrl(featured)}"><span class="feature-icon">${icon('spark')}</span><span class="feature-copy"><span class="eyebrow">GỢI Ý ĐỂ BẮT ĐẦU</span><strong>${E(featured.title)}</strong></span><span class="feature-read">${featured.minutes} phút đọc</span><span class="circle-arrow">${icon('arrow')}</span></a></section><div class="topic-strip"><div class="container">${['TRÍ TUỆ NHÂN TẠO','CUỘC SỐNG SỐ','KẾT NỐI THÔNG MINH','THỦ THUẬT THỰC TẾ','AN TOÀN MỖI NGÀY'].map(t=>`<span>${t}<i>✦</i></span>`).join('')}</div></div><section class="container section explore-section" id="kham-pha"><div class="section-heading"><div><div class="eyebrow">01 / CHỌN MỘT GÓC NHÌN</div><h2>Bạn muốn khám phá gì?</h2></div><p>Không cần biết mọi thứ.<br>Chỉ cần bắt đầu từ điều bạn thích.</p></div><div class="category-grid">${data.categories.map((c,i)=>`<a class="category-tile category-${c.id}" href="#bai-viet" data-select-category="${c.id}"><span class="category-top"><span class="category-icon">${icon(c.icon)}</span><span class="category-number">0${i+1}</span></span><h3>${E(c.name)}</h3><p>${E(c.description)}</p><span class="category-bottom"><span>${data.articles.filter(a=>a.category===c.id).length} cẩm nang</span>${icon('arrow')}</span></a>`).join('')}</div></section><section class="container section articles-section" id="bai-viet"><div class="section-heading"><div><div class="eyebrow">02 / ĐỌC CHẬM, HIỂU SÂU</div><h2>Một chút công nghệ,<br>nhiều điều hữu ích.</h2></div><button class="text-button" id="saved-toggle" aria-pressed="false">${icon('bookmark')}Bài đã lưu <span id="saved-count">0</span></button></div><div class="filter-bar"><div class="filter-tabs" role="group" aria-label="Lọc bài theo chuyên mục"><button class="filter-tab active" data-category="all" aria-pressed="true">Tất cả</button>${data.categories.map(c=>`<button class="filter-tab" data-category="${c.id}" aria-pressed="false">${E(c.short||c.name)}</button>`).join('')}</div><div class="filter-tools"><label class="inline-search">${icon('search')}<input type="search" id="article-search" placeholder="Tìm cẩm nang…" maxlength="100" aria-label="Tìm kiếm trong cẩm nang"></label><label class="sr-only" for="article-sort">Sắp xếp bài</label><select id="article-sort"><option value="newest">Mới nhất</option><option value="oldest">Cũ nhất</option><option value="shortest">Đọc nhanh</option></select></div></div><p id="filter-status" class="filter-status" aria-live="polite">${data.articles.length} cẩm nang dành cho bạn</p><div class="article-grid" id="article-grid">${data.articles.slice(0,6).map(a=>card(a)).join('')}</div><div class="empty-state" id="empty-state" hidden>${icon('search')}<h3>Chưa tìm thấy cẩm nang phù hợp</h3><p>Thử từ khóa khác hoặc khám phá tất cả bài viết.</p><button class="button button-outline" id="clear-filters">Xem tất cả cẩm nang</button></div><div class="load-more"><button class="button button-outline" id="load-more">Xem thêm cẩm nang${icon('right')}</button></div><noscript><p>Hãy bật JavaScript để tìm kiếm và lưu bài. <a href="tat-ca.html">Xem đầy đủ danh sách cẩm nang.</a></p></noscript></section><section class="about-band" id="ve-kenh"><div class="container about-grid"><div class="about-visual"><div class="about-orbit orbit-one"></div><div class="about-orbit orbit-two"></div><div class="about-monogram">TH<span>TECH HORIZON</span></div><span class="about-caption"><span class="live-dot"></span> GIỮ SỰ TÒ MÒ, MỞ TẦM NHÌN</span></div><div class="about-copy"><div class="eyebrow">03 / CÂU CHUYỆN CỦA KÊNH</div><h2>Công nghệ thay đổi.<br>Sự tò mò ở lại.</h2><p class="about-lead">Tech Horizon bắt đầu từ một ý tưởng giản dị: <strong>công nghệ nên dễ hiểu hơn với mọi người.</strong></p><p>Từ một khái niệm AI còn lạ, một thông số thiết bị khó đọc đến một thao tác nhỏ giúp bạn làm việc thuận tiện hơn — mỗi chủ đề là một cơ hội để hiểu thêm.</p><div class="about-values"><div>${icon('spark')}<span><strong>Dễ hiểu trước tiên</strong><small>Giải thích rõ, có ví dụ thực tế.</small></span></div><div>${icon('shield')}<span><strong>Biết rõ điều mình đọc</strong><small>Cẩm nang có nguồn để đối chiếu.</small></span></div></div><p class="editorial-note">${E(cfg.contentNote)}</p></div></div></section><section class="container section community-section" id="cong-dong"><div class="community-card"><div class="community-copy"><div class="eyebrow"><span class="live-dot"></span> HẸN GẶP BẠN TRÊN FACEBOOK</div><h2>Thêm một góc nhìn.<br><span>Thêm một kết nối.</span></h2><p>Theo dõi Tech Horizon, cùng trao đổi những điều bạn tò mò và gợi ý chủ đề bạn muốn khám phá tiếp theo.</p><button class="button button-blue" data-facebook>${fb}Đến kênh Tech Horizon${icon('arrow')}</button><span class="facebook-status" data-facebook-status>Liên kết Facebook chính thức đang chờ cập nhật.</span></div><div class="community-art" aria-hidden="true"><span class="community-orbit"></span><span class="fb-cube">f</span><span class="community-star">✳</span><span class="message-bubble">Công nghệ khó hiểu?<br><strong>Cùng khám phá nhé.</strong><span>TECH HORIZON ↗</span></span></div></div><div class="connect-grid"><div><div class="eyebrow">CÙNG TẠO NÊN NỘI DUNG HỮU ÍCH</div><h3>Bạn tò mò điều gì?</h3><p>Một câu hỏi nhỏ của bạn có thể trở thành<br>chủ đề tiếp theo của Tech Horizon.</p><a class="text-button" id="email-link" hidden>${icon('mail')}Liên hệ qua email${icon('arrow')}</a></div><form id="topic-form" class="topic-form"><label for="topic-name">Bạn muốn khám phá chủ đề nào?</label><div class="topic-input"><input id="topic-name" required minlength="3" maxlength="300" placeholder="Ví dụ: Cách chọn RAM cho laptop…"><button type="submit" aria-label="Soạn gợi ý chủ đề">${icon('arrow')}</button></div><p>Soạn nội dung để bạn sao chép và gửi cho kênh.</p></form></div></section><section class="container section faq-section"><div class="section-heading"><div><div class="eyebrow">MỘT VÀI ĐIỀU BẠN CÓ THỂ MUỐN BIẾT</div><h2>Hỏi nhanh, đáp gọn.</h2></div></div><div class="faq-list"><details><summary>Tech Horizon dành cho ai?<span>+</span></summary><p>Dành cho những ai tò mò về công nghệ, kể cả khi bạn mới bắt đầu. Website ưu tiên kiến thức nền tảng, cách giải thích rõ và những việc có thể áp dụng trong cuộc sống số.</p></details><details><summary>Bài đã lưu có xuất hiện trên điện thoại khác không?<span>+</span></summary><p>Bài đã lưu được giữ ngay trong trình duyệt bạn đang dùng. Chúng không tự đồng bộ sang thiết bị khác và có thể mất khi bạn xóa dữ liệu trình duyệt. Bạn có thể chia sẻ hoặc sao chép liên kết bài để lưu ở nơi khác.</p></details><details><summary>Nội dung website có tự lấy từ Facebook không?<span>+</span></summary><p>Các cẩm nang hiện tại được biên soạn cho website. Website không tự truy cập tài khoản Facebook hoặc đồng bộ bài đăng. Khi có bài mới được cập nhật, bạn có thể đọc trong phần Cẩm nang.</p></details><details><summary>Làm sao góp ý nội dung hoặc đề xuất hợp tác?<span>+</span></summary><p>Chuẩn bị nội dung qua ô gợi ý chủ đề phía trên rồi gửi cho kênh qua đường dẫn Facebook chính thức khi đã được cập nhật. Email liên hệ sẽ hiển thị nếu chủ kênh bổ sung.</p></details></div></section></main>${footer()}</body></html>`;
}
function legacyArticle(a){
 const p='../';const c=cat(a);
 const ld={'@context':'https://schema.org','@type':'Article',headline:a.title,description:a.excerpt,datePublished:a.date,dateModified:a.date,inLanguage:'vi-VN',author:{'@type':'Organization',name:cfg.name},publisher:{'@type':'Organization',name:cfg.name},mainEntityOfPage:`${base}/bai-viet/${a.id}.html`,image:`${base}/assets/horizon-globe.webp`};
 return head(`${a.title} — ${cfg.name}`,a.excerpt,p,`bai-viet/${a.id}.html`,'article')+`<script type="application/ld+json">${JSON.stringify(ld).replace(/</g,'\\u003c')}</script></head><body data-page="article" data-article="${a.id}" data-base="../"><div class="reading-progress" id="reading-progress"></div>${header(p)}<main id="main" class="container article-layout"><nav class="breadcrumb" aria-label="Vị trí trang"><a href="../index.html">Trang chủ</a>${icon('right')}<a href="../index.html#bai-viet">Cẩm nang</a>${icon('right')}<span>${E(c.name)}</span></nav><header class="article-header" id="article-header">${tag(a)}<h1>${E(a.title)}</h1><p class="article-intro">${E(a.excerpt)}</p><div class="article-byline"><span class="mini-avatar">TH</span><div><strong>${E(cfg.name)}</strong><div class="meta">${miniMeta(a)}</div></div><div class="article-actions"><button class="icon-button bookmark" data-save="${a.id}" aria-label="Lưu bài" aria-pressed="false">${icon('bookmark')}</button><button class="icon-button" data-share="${a.id}" aria-label="Chia sẻ bài viết">${icon('share')}</button></div></div></header><div class="article-cover"><img src="${imageUrl(a,p)}" width="640" height="400" alt="Minh họa chủ đề ${E(c.name)}"></div><div class="article-content-layout"><aside class="article-sidebar"><div class="toc"><span class="eyebrow">TRONG CẨM NANG NÀY</span><nav aria-label="Mục lục bài viết" id="article-toc">${a.sections.map((s,i)=>`<a href="#phan-${i+1}"><span>0${i+1}</span>${E(s.heading)}</a>`).join('')}</nav><a class="text-button" href="../index.html#bai-viet">${icon('right')}Khám phá cẩm nang khác</a></div></aside><article class="prose" id="article-body"><div class="takeaway">${icon('spark')}<div><strong>Mang theo một điều</strong><p>${E(a.takeaway)}</p></div></div>${a.sections.map((s,i)=>`<section id="phan-${i+1}"><span class="section-index">0${i+1}</span><h2>${E(s.heading)}</h2><p>${E(s.text)}</p></section>`).join('')}<div class="article-sources"><h3>Nguồn để bạn đọc thêm</h3><ul>${a.sources.map(s=>`<li><a href="${E(s.url)}" target="_blank" rel="noopener noreferrer">${E(s.label)}${icon('external')}</a></li>`).join('')}</ul></div><p class="editorial-note">${E(cfg.contentNote)}</p><div class="reading-end"><span>Hiểu thêm một điều.<br><strong>Mở thêm một góc nhìn.</strong></span><button class="button button-outline" data-share="${a.id}">${icon('share')}Chia sẻ cẩm nang</button></div></article></div><section class="section related-section"><div class="section-heading"><div><div class="eyebrow">TIẾP TỤC SỰ TÒ MÒ</div><h2>Có thể bạn cũng thích.</h2></div><a class="text-button" href="../index.html#bai-viet">Tất cả cẩm nang${icon('arrow')}</a></div><div class="article-grid">${data.articles.filter(x=>x.id!==a.id).sort((x,y)=>Number(y.category===a.category)-Number(x.category===a.category)).slice(0,3).map(x=>card(x,p)).join('')}</div></section></main>${footer(p)}</body></html>`;
}
function policy(){return head(`Quyền riêng tư — ${cfg.name}`,'Cách website Tech Horizon sử dụng bộ nhớ trình duyệt và các liên kết ngoài.','','chinh-sach.html')+`</head><body data-page="policy" data-base="">${header()}<main id="main" class="container policy-page"><div class="eyebrow">RÕ RÀNG ĐỂ BẠN AN TÂM</div><h1>Quyền riêng tư</h1><p class="article-intro">Những điều cần biết khi bạn đọc và sử dụng website.</p><div class="prose"><section><h2>Dữ liệu lưu trong trình duyệt</h2><p>Website lưu lựa chọn giao diện và danh sách mã bài đã lưu trong localStorage của trình duyệt. Bản nháp tạo bằng Bàn biên tập cũng nằm trên thiết bị đó. Dữ liệu này không tự đồng bộ giữa các thiết bị. Bạn có thể xóa qua công cụ dưới đây hoặc phần quản lý dữ liệu website của trình duyệt.</p><a class="button button-outline" href="du-lieu.html">Sao lưu và quản lý dữ liệu trên thiết bị</a></section><section><h2>Biểu mẫu gợi ý</h2><p>Ô gợi ý chủ đề chỉ chuẩn bị văn bản để bạn chủ động sao chép và gửi cho kênh. Website không tự gửi biểu mẫu, email hoặc tin nhắn, và không lưu gợi ý vào máy chủ.</p></section><section><h2>Liên kết bên ngoài</h2><p>Khi bạn mở Facebook, email hoặc nguồn tham khảo, dịch vụ đó áp dụng chính sách riêng. Website không yêu cầu mật khẩu Facebook, mã OTP hay quyền truy cập tài khoản của bạn.</p></section><section><h2>Hạ tầng lưu trữ</h2><p>Bản website này không cài công cụ phân tích hoặc quảng cáo của bên thứ ba. Dịch vụ lưu trữ có thể xử lý thông tin truy cập kỹ thuật theo chính sách riêng. Nếu chủ kênh bổ sung các dịch vụ khác, chính sách cần được cập nhật tương ứng.</p></section><section><h2>Góp ý và liên hệ</h2><p>Vui lòng dùng đường dẫn Facebook chính thức hoặc email do chủ kênh cập nhật tại phần Cộng đồng. Không gửi dữ liệu nhạy cảm trong nội dung góp ý.</p></section></div></main>${footer()}</body></html>`;}

function head(...args){return legacyHead(...args)+`<link rel="stylesheet" href="${args[2]||''}assets/premium.css"><script src="${args[2]||''}assets/premium.js" defer></script><link rel="stylesheet" href="${args[2]||''}assets/studio.css"><script src="${args[2]||''}assets/workbench.js" defer></script><script src="${args[2]||''}assets/studio.js" defer></script><link rel="stylesheet" href="${args[2]||''}assets/creator.css"><script>try{const p=JSON.parse(localStorage.getItem('th-preferences'));if(p&&[1,1.12,1.25].includes(p.scale)){document.documentElement.style.setProperty('--ui-scale',p.scale);document.documentElement.dataset.motion=p.motion==='reduce'?'reduce':'system';document.documentElement.dataset.contrast=String(p.contrast===true)}}catch(e){}</script><script src="${args[2]||''}assets/creator-core.js" defer></script><script src="${args[2]||''}assets/creator-markup.js" defer></script><script src="${args[2]||''}assets/creator.js" defer></script><script src="${args[2]||''}assets/media-tools.js" defer></script><link rel="stylesheet" href="${args[2]||''}assets/experience.css"><script src="${args[2]||''}assets/experience-core.js" defer></script><script src="${args[2]||''}assets/experience-markup.js" defer></script><script src="${args[2]||''}assets/experience.js" defer></script>`;}
function header(p=''){return `<a class="skip-link" href="#main">Đến nội dung chính</a><div class="preview-banner" id="preview-banner" hidden>Bạn đang xem bản nháp trên thiết bị này. <a href="${p}bien-tap.html">Bàn biên tập</a><button id="exit-preview">Thoát xem trước</button></div><header class="site-header"><div class="container header-inner">${brand(p)}<nav class="desktop-nav" aria-label="Điều hướng chính"><a href="${p}index.html#bai-viet">Cẩm nang</a><a href="${p}index.html#diem-bat-dau">Khám phá theo gu</a><a href="${p}studio.html">Studio</a><a href="${p}gioi-thieu.html">Về kênh</a></nav><div class="header-actions"><button class="icon-button" data-open-search aria-label="Tìm kiếm bài viết">${icon('search')}</button><button class="icon-button theme-toggle" aria-label="Chuyển giao diện sáng hoặc tối">${icon('sun')}</button>${C.url(cfg.facebookUrl,true)?`<button class="button button-small button-blue desktop-follow" data-facebook>${fb}Theo dõi${icon('arrow')}</button>`:`<a class="button button-small button-blue header-discover" href="${p}index.html#diem-bat-dau">Bắt đầu khám phá ${icon('arrow')}</a>`}<button class="icon-button menu-button" aria-label="Mở menu" aria-controls="mobile-menu" aria-expanded="false">${icon('menu')}</button></div></div><nav id="mobile-menu" class="mobile-menu" aria-label="Điều hướng điện thoại" hidden><a href="${p}index.html#bai-viet">Cẩm nang công nghệ</a><a href="${p}studio.html">Studio công nghệ</a><a href="${p}chuyen-de.html">Chuyên đề & lộ trình đọc</a><a href="${p}thuat-ngu.html">Từ điển thuật ngữ</a><a href="${p}thu-vien.html">Thư viện cá nhân</a><a href="${p}index.html#ve-kenh">Về Tech Horizon</a><a href="${p}index.html#cong-dong">Kết nối cộng đồng</a><a href="${p}gioi-thieu.html">Giới thiệu & hợp tác</a><a href="${p}dieu-hanh.html">Trạm điều hành</a><a href="${p}du-lieu.html">Dữ liệu & hiển thị</a><a href="${p}huong-dan.html">Hướng dẫn sử dụng</a><button data-facebook>${fb}Theo dõi Facebook${icon('arrow')}</button></nav></header>`;}
function sectionHeading(number,kicker,title,link='',label='Khám phá thêm'){return `<div class="section-heading"><div><div class="eyebrow">${number} / ${kicker}</div><h2>${title}</h2></div>${link?`<a class="text-button" href="${link}">${label}${icon('arrow')}</a>`:''}</div>`;}
function spotlight(){
 const chosen=['tu-ghi-chu-den-ke-hoach-voi-ai','ssd-hdd-khac-nhau','https-khong-du-de-tin-tuong'].map((id,i)=>data.articles.find(a=>a.id===id)||data.articles[i]).filter(Boolean);
 if(!chosen.length)return '';
 return `<section class="container section spotlight-section" id="tieu-diem">${sectionHeading('TH','ĐIỂM HẸN CỦA SỰ TÒ MÒ','Có điều mới để hiểu hôm nay.')}<div class="spotlight-grid">${chosen.map((a,i)=>`<a class="spotlight-card ${i===0?'spotlight-lead':''}" href="${articleUrl(a)}"><img src="${i===0?'assets/horizon-portal.webp':imageUrl(a)}" width="640" height="400" alt="" loading="lazy"><div class="spotlight-content">${tag(a)}<h3>${E(a.title)}</h3><p>${E(a.excerpt)}</p><span>${a.minutes} phút để mở một góc nhìn ${icon('arrow')}</span></div></a>`).join('')}</div><div id="continue-reading" class="continue-reading" hidden></div></section>`;
}
function journeyCard(j,i=0,p=''){
 const list=j.articles.map(id=>data.articles.find(a=>a.id===id)).filter(Boolean),total=list.reduce((n,a)=>n+a.minutes,0);
 return `<article class="journey-card journey-${E(j.category||'ai')}" id="${E(j.id)}"><div class="journey-heading"><span class="journey-no">0${i+1}</span><span class="tag">${list.length} cẩm nang · ${total} phút</span></div><h3>${E(j.title)}</h3><p>${E(j.description)}</p><div class="journey-progress" data-journey-progress="${E(j.id)}"><span style="width:0%"></span></div><span class="journey-progress-text" data-journey-text="${E(j.id)}">Chưa bắt đầu trên thiết bị này</span><ol>${list.map((a,n)=>`<li><a href="${articleUrl(a,p)}" data-journey-article="${a.id}"><span>${String(n+1).padStart(2,'0')}</span><strong>${E(a.title)}</strong>${icon('right')}</a></li>`).join('')}</ol>${list.length?`<a class="text-button" href="${articleUrl(list[0],p)}" data-journey-start="${E(j.id)}">Bắt đầu lộ trình${icon('arrow')}</a>`:''}</article>`;
}
function journeyTeaser(){if(!data.journeys?.length)return '';return `<section class="container section journey-section" id="lo-trinh">${sectionHeading('TH','ĐỌC THEO MỘT MẠCH','Đi từng bước.<br>Hiểu thành một bức tranh.','chuyen-de.html','Tất cả lộ trình')}<div class="journey-grid">${data.journeys.slice(0,2).map((j,i)=>journeyCard(j,i)).join('')}</div></section>`;}
function libraryBanner(){return `<section class="container library-banner"><div class="library-banner-icon">${icon('bookmark')}</div><div><div class="eyebrow">GÓC ĐỌC CỦA RIÊNG BẠN</div><h3>Sự tò mò không cần đọc hết trong một lần.</h3><p>Lưu bài, ghi chú và tiếp tục ở nơi bạn đã dừng.</p></div><a class="button button-outline" href="thu-vien.html">Mở thư viện${icon('arrow')}</a></section>`;}
function glossaryTeaser(){if(!data.glossary?.length)return '';const terms=['dns','https','prompt','ram'].map(id=>data.glossary.find(t=>t.id===id)).filter(Boolean);return `<section class="container section glossary-teaser">${sectionHeading('TH','MỘT TỪ MỚI, MỘT ĐIỀU SÁNG TỎ','Gặp thuật ngữ lạ?<br>Cùng hiểu cho rõ.','thuat-ngu.html','Mở từ điển')}<div class="glossary-mini-grid">${terms.map(t=>`<a href="thuat-ngu.html#${t.id}"><span>${E(t.term)}</span><p>${E(t.definition)}</p>${icon('arrow')}</a>`).join('')}</div></section>`;}
function socialSection(){if(!data.socialPosts?.length)return '';return `<section class="container section social-posts">${sectionHeading('FB','TỪ KÊNH FACEBOOK','Những chia sẻ từ Tech Horizon.')}<div class="social-grid">${data.socialPosts.map(p=>`<a class="social-post" href="${E(p.url)}" target="_blank" rel="noopener noreferrer">${fb}<span><strong>${E(p.title)}</strong><p>${E(p.caption)}</p><small>Mở bài viết trên Facebook</small></span>${icon('arrow')}</a>`).join('')}</div></section>`;}
function home(){let h=legacyHome();
 h=h.replace(/<section class="hero container"[\s\S]*?<\/section>/,Experience.hero(data,C));
 h=h.replace(/<div class="topic-strip"><div class="container">[\s\S]*?<\/div><\/div>/,Experience.strip(data)+Experience.discovery(data,C,X));
 h=h.replace('<section class="container section explore-section"',spotlight()+'<section class="container section explore-section"');
 h=h.replace('<section class="container section articles-section"',Experience.lab(data,C,X)+'<section class="container section articles-section"');
 h=h.replace('<section class="about-band"',studioTeaser()+journeyTeaser()+libraryBanner()+'<section class="about-band"');
 h=h.replace('<section class="container section faq-section">',socialSection()+glossaryTeaser()+'<section class="container section faq-section">');
 h=h.replace(/href="#bai-viet" data-select-category="([a-z0-9-]+)"/g, 'href="chuyen-muc/$1.html" data-select-category="$1"');
 h=h.replace('<footer class="site-footer">','<section class="container home-owner-strip"><div><div class="eyebrow">DÀNH CHO NGƯỜI LÀM NỘI DUNG</div><h2>Mang ý tưởng của bạn tới góc sáng tạo.</h2></div><div><a class="text-button" href="dieu-hanh.html">Lập kế hoạch ↗</a><a class="text-button" href="huong-dan.html">Hướng dẫn sử dụng ↗</a></div></section><footer class="site-footer">');
 return h;
}
function readerTools(){return `<div class="reader-tools" role="group" aria-label="Tùy chọn đọc"><div><span>Góc đọc của bạn</span><button class="reader-control" data-font="smaller" aria-label="Giảm cỡ chữ">A−</button><button class="reader-control" data-font="larger" aria-label="Tăng cỡ chữ">A+</button></div><div><button class="reader-control" id="focus-reading" aria-pressed="false">Chế độ tập trung</button><button class="reader-control" id="speak-article" aria-pressed="false">Nghe bài</button><button class="reader-control" id="print-article">In / PDF</button></div></div>`;}
function notebook(a){return `<section class="reader-notebook" data-notebook="${a.id}"><div><span class="eyebrow">MANG THEO ĐIỀU BẠN HIỂU</span><h2>Một dòng ghi lại,<br>một điều nhớ lâu hơn.</h2><p>Ghi chú lưu riêng trên trình duyệt này. Bạn có thể sao lưu từ Thư viện cá nhân.</p></div><div><label for="reader-note">Ghi chú của bạn</label><textarea id="reader-note" maxlength="3000" placeholder="Điều mình muốn thử sau khi đọc bài này…" rows="5"></textarea><div class="notebook-actions"><button class="button button-outline" id="save-reader-note">Lưu ghi chú</button><button class="text-button" id="mark-read">Đánh dấu đã đọc ${icon('check')}</button></div><p id="note-status" role="status" aria-live="polite"></p></div></section>`;}
function article(a){return legacyArticle(a).replace('<div class="article-cover">',readerTools()+'<div class="article-cover">').replace('<section class="section related-section">',notebook(a)+'<section class="section related-section">');}
function pageHero(kicker,title,intro,count=''){return `<div class="page-hero"><div class="eyebrow"><span class="live-dot"></span>${kicker}</div><h1>${title}</h1><p>${E(intro)}</p>${count?`<span class="page-count">${count}</span>`:''}</div>`;}
function categoryPage(c){const list=data.articles.filter(a=>a.category===c.id);return head(`${c.name} — ${cfg.name}`,c.description,'../',`chuyen-muc/${c.id}.html`)+`</head><body data-page="category" data-category="${c.id}" data-base="../">${header('../')}<main class="container" id="main">${pageHero('CHUYÊN MỤC / '+E(c.name).toUpperCase(),E(c.name)+'.<br>Một góc nhìn sâu hơn.',c.description,`${list.length} cẩm nang`)}<div class="category-page-nav">${data.categories.map(cat=>`<a ${cat.id===c.id?'aria-current="page"':''} href="${cat.id}.html">${E(cat.name)}</a>`).join('')}</div><div class="category-search"><label for="category-query">Tìm trong chuyên mục</label><input id="category-query" type="search" maxlength="100" placeholder="Bạn đang tò mò về…"><span id="category-count" role="status">${list.length} kết quả</span></div><div class="article-grid category-page-grid" id="category-page-grid">${list.map(a=>card(a,'../')).join('')}</div><div id="category-empty" class="empty-state" hidden>Chưa tìm thấy bài. Thử từ khóa khác nhé.</div></main>${footer('../')}</body></html>`;}
function journeysPage(){return head(`Chuyên đề & lộ trình đọc — ${cfg.name}`,'Lộ trình tìm hiểu AI, thiết bị, thủ thuật và an toàn số theo từng bước.','','chuyen-de.html')+`</head><body data-page="journeys" data-base="">${header()}<main id="main" class="container">${pageHero('CHUYÊN ĐỀ / ĐỌC CÓ MỘT MẠCH','Bắt đầu từ một câu hỏi.<br>Đi đến một góc nhìn.', 'Chọn một lộ trình, đọc từng cẩm nang và theo dõi tiến độ của riêng bạn. Mỗi chủ đề kết nối các kiến thức theo thứ tự gợi ý.',`${data.journeys?.length||0} lộ trình · ${data.articles.length} cẩm nang`)}<div class="journey-grid all-journeys">${(data.journeys||[]).map((j,i)=>journeyCard(j,i)).join('')}</div><div class="journey-footnote">${icon('bookmark')}<p>Tiến độ được ghi lại trên trình duyệt này. Bạn có thể xuất bản sao lưu trong <a href="thu-vien.html">Thư viện cá nhân</a>.</p></div></main>${footer()}</body></html>`;}
function glossaryPage(){const terms=data.glossary||[];return head(`Từ điển công nghệ — ${cfg.name}`,'Tra cứu thuật ngữ công nghệ bằng cách giải thích ngắn, dễ hiểu và có nguồn để đọc thêm.','','thuat-ngu.html')+`</head><body data-page="glossary" data-base="">${header()}<main id="main" class="container">${pageHero('TỪ ĐIỂN / HIỂU TỪ GỐC','Một từ mới.<br>Một điều sáng tỏ.', 'Không cần nhớ mọi chữ viết tắt. Tra nhanh, hiểu ý chính và mở nguồn để tìm hiểu thêm.',`${terms.length} thuật ngữ`)}<div class="glossary-toolbar"><label class="glossary-search">${icon('search')}<input type="search" id="term-query" maxlength="100" placeholder="Thử DNS, HTTPS, RAM, API…" aria-label="Tìm thuật ngữ"></label><label class="sr-only" for="term-category">Lọc theo chuyên mục</label><select id="term-category"><option value="all">Mọi chủ đề</option>${data.categories.map(c=>`<option value="${c.id}">${E(c.name)}</option>`).join('')}</select><span id="term-count" role="status">${terms.length} thuật ngữ</span></div><div class="terms-grid" id="terms-grid">${terms.map(t=>`<article class="term-card" id="${E(t.id)}" data-term="${E(t.id)}"><span class="term-category">${E(data.categories.find(c=>c.id===t.category)?.short||'Công nghệ')}</span><h2>${E(t.term)}</h2><p>${E(t.definition)}</p><a href="${E(t.url)}" target="_blank" rel="noopener noreferrer">Đọc thêm từ nguồn ${icon('external')}</a></article>`).join('')}</div><div class="empty-state" id="term-empty" hidden>Chưa có thuật ngữ phù hợp với từ khóa này.</div><p class="glossary-disclaimer">Các định nghĩa được viết ngắn để định hướng; từng công nghệ có thể có phạm vi và chi tiết rộng hơn.</p></main>${footer()}</body></html>`;}
function libraryPage(){return head(`Thư viện cá nhân — ${cfg.name}`,'Bài đã lưu, tiến độ đọc và ghi chú của bạn trên Tech Horizon.','','thu-vien.html')+`<meta name="robots" content="noindex"></head><body data-page="library" data-base="">${header()}<main id="main" class="container library-page">${pageHero('THƯ VIỆN / DÀNH RIÊNG CHO BẠN','Để dành sự tò mò.<br>Tiếp tục khi bạn muốn.', 'Nơi giữ những bài bạn thích, tiến độ đọc và ghi chú trên trình duyệt này. Không cần tạo tài khoản.')}<div class="library-stats"><div><span id="library-saved-count">0</span><small>CẨM NANG ĐÃ LƯU</small></div><div><span id="library-progress-count">0</span><small>ĐANG ĐỌC</small></div><div><span id="library-completed-count">0</span><small>ĐÃ ĐỌC XONG</small></div><div><span id="library-notes-count">0</span><small>GHI CHÚ CỦA BẠN</small></div></div><div class="library-tools"><div class="filter-tabs" role="group" aria-label="Lọc thư viện"><button class="filter-tab active" data-library-tab="saved" aria-pressed="true">Đã lưu</button><button class="filter-tab" data-library-tab="reading" aria-pressed="false">Đang đọc</button><button class="filter-tab" data-library-tab="completed" aria-pressed="false">Đã đọc</button><button class="filter-tab" data-library-tab="notes" aria-pressed="false">Ghi chú</button></div><div><button class="text-button" id="export-reader">Sao lưu thư viện ${icon('arrow')}</button><label class="text-button import-reader-label">Khôi phục<input id="import-reader" type="file" accept=".json,application/json" class="sr-only"></label></div></div><div id="library-results" class="library-results" aria-live="polite"></div><div class="empty-state" id="library-empty"><span class="eyebrow">MỘT GÓC ĐỌC CHỜ BẠN</span><h3>Chưa có cẩm nang ở đây.</h3><p>Nhấn biểu tượng lưu trên bài bạn thích, hoặc mở một bài để bắt đầu.</p><a class="button button-blue" href="index.html#bai-viet">Khám phá cẩm nang ${icon('arrow')}</a></div><div class="reader-data-note"><strong>Bạn kiểm soát dữ liệu của mình.</strong><p>Bản sao lưu chứa tiến độ và ghi chú bạn đã nhập. Hãy cất tệp ở nơi riêng tư. Dữ liệu không tự đồng bộ qua thiết bị và có thể mất khi bạn xóa bộ nhớ trình duyệt.</p><button class="text-button" id="clear-reading-history">Xóa tiến độ và ghi chú trên thiết bị này</button><span id="library-status" role="status"></span></div></main>${footer()}</body></html>`;}
function studioTeaser(){return `<section class="container studio-teaser"><div><div class="eyebrow">NƠI KIẾN THỨC THÀNH THAO TÁC</div><h2>Đọc để hiểu.<br><span>Thử để làm chủ.</span></h2><p>Mở Studio, mang một câu hỏi hoặc một con số tới và thực hành ngay trên thiết bị của bạn.</p><a class="button button-blue" href="studio.html">Mở Studio công nghệ ${icon('arrow')}</a></div><div class="studio-teaser-grid">${W.catalog.map((t,i)=>`<a href="studio.html#${t.id}"><span>0${i+1}</span>${icon(t.icon)}<h3>${E(t.title)}</h3><p>${E(t.description)}</p></a>`).join('')}</div></section>`;}
function studioPage(){return head(`Studio công nghệ — ${cfg.name}`,'Công cụ thực hành: xây prompt, ước lượng tải tệp, tạo liên kết UTM và rà soát nội dung.','','studio.html')+`</head><body data-page="studio" data-base="">${header()}<main class="container studio-page" id="main">${Studio.body(W)}</main>${footer()}</body></html>`;}
function creatorPage(page,file,title,intro){return head(title+' — '+cfg.name,intro,'',file)+(page==='planner'||page==='settings'?'<meta name="robots" content="noindex,nofollow">':'')+`</head><body data-page="${page}" data-base="">${header()}<main class="container command-page" id="main">${Creator.body(page,data,C,K)}</main>${footer()}</body></html>`;}
const files={};
for(const [page,file,title,intro] of [['planner','dieu-hanh.html','Trạm điều hành','Kế hoạch nội dung và lịch làm việc trên trình duyệt.'],['settings','du-lieu.html','Dữ liệu & hiển thị','Sao lưu toàn bộ dữ liệu thiết bị và tùy chỉnh trải nghiệm đọc.'],['kit','gioi-thieu.html','Giới thiệu & hợp tác',cfg.description],['guide','huong-dan.html','Hướng dẫn sử dụng','Hướng dẫn vận hành và xuất bản website Tech Horizon.']])files[file]=creatorPage(page,file,title,intro);
files['studio.html']=studioPage();
files['index.html']=home();files['chinh-sach.html']=policy().replace('Website lưu lựa chọn giao diện và danh sách mã bài đã lưu','Website lưu lựa chọn giao diện, cỡ chữ, danh sách mã bài đã lưu, tiến độ đọc, ghi chú cá nhân, prompt và kịch bản nháp, dấu chọn tự rà soát, kế hoạch nội dung và tùy chọn hỗ trợ hiển thị');
for(const a of data.articles)files['bai-viet/'+a.id+'.html']=article(a);
for(const c of data.categories)files['chuyen-muc/'+c.id+'.html']=categoryPage(c);
files['chuyen-de.html']=journeysPage();files['thuat-ngu.html']=glossaryPage();files['thu-vien.html']=libraryPage();
files['tat-ca.html']=head(`Tất cả cẩm nang — ${cfg.name}`,cfg.description,'','tat-ca.html')+`</head><body data-base="">${header()}<main class="container section" id="main">${pageHero('THƯ VIỆN CÔNG NGHỆ','Cẩm nang để đọc.<br>Kiến thức để dùng.',cfg.description,`${data.articles.length} cẩm nang`)}<div class="article-grid">${data.articles.map(a=>card(a)).join('')}</div></main>${footer()}</body></html>`;
files['404.html']=head(`Không tìm thấy trang — ${cfg.name}`,'Quay lại khám phá cẩm nang Tech Horizon.')+`<meta name="robots" content="noindex"></head><body><main class="container error-page" id="main"><span class="eyebrow">TECH HORIZON / 404</span><h1>Góc nhìn này<br>chưa có ở đây.</h1><p>Đường dẫn có thể đã thay đổi. Bạn vẫn còn rất nhiều điều để khám phá.</p><a class="button button-blue" href="${base||'.'}/index.html">Về trang chủ ${icon('arrow')}</a></main></body></html>`;
files['doc-bai.html']=head(`Đọc cẩm nang — ${cfg.name}`,'Cẩm nang công nghệ Tech Horizon.','','doc-bai.html')+`<meta name="robots" content="noindex"></head><body data-page="dynamic-article" data-base="">${header()}<main id="main" class="container article-layout"><div id="dynamic-article"></div></main>${footer()}</body></html>`;
files['assets/static-routes.js']='window.TH_STATIC_ROUTES = '+JSON.stringify(data.articles.map(a=>a.id))+';\n';
files['site-data.js']='/* Nội dung công khai của Tech Horizon. */\nwindow.TECH_HORIZON = '+JSON.stringify(data,null,2).replace(/</g,'\\u003c')+';\n';
files['robots.txt']=`User-agent: *\nAllow: /\nDisallow: /bien-tap.html\nDisallow: /thu-vien.html\nDisallow: /dieu-hanh.html\nDisallow: /du-lieu.html\n${base?'Sitemap: '+base+'/sitemap.xml\n':''}`;
const pages=['index.html','tat-ca.html','chinh-sach.html','chuyen-de.html','thuat-ngu.html','studio.html','gioi-thieu.html','huong-dan.html',...data.categories.map(c=>'chuyen-muc/'+c.id+'.html'),...data.articles.map(a=>'bai-viet/'+a.id+'.html')];
files['sitemap.xml']=`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${pages.map(file=>`<url><loc>${E(base+'/'+file)}</loc></url>`).join('')}</urlset>`;
files['feed.xml']=`<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>${E(cfg.name)}</title><link>${E(base)}</link><description>${E(cfg.description)}</description><language>vi</language>${data.articles.map(a=>`<item><title>${E(a.title)}</title><link>${E(base+'/'+articleUrl(a))}</link><guid isPermaLink="true">${E(base+'/'+articleUrl(a))}</guid><description>${E(a.excerpt)}</description><pubDate>${new Date(a.date+'T08:00:00+07:00').toUTCString()}</pubDate></item>`).join('')}</channel></rss>`;
return files;
}
const api={build};if(typeof module==='object'&&module.exports)module.exports=api;else root.THRenderer=api;
})(typeof window!=='undefined'?window:globalThis);
